import { readFileSync } from "node:fs";
import { join } from "node:path";
import type { FileInput } from "../load";

// Synthetic WoW Forever Data Export, generated by
// scripts/make-forever-fixture.mjs. Every file starts with a UTF-8 BOM.
export const FIXTURE_DIR = "__fixtures__/forever";

export const DESKTOP_KINDS = [
  "Sales",
  "Buys",
  "Cancelled",
  "Expired",
  "Income",
  "Expense",
] as const;
export type DesktopKind = (typeof DESKTOP_KINDS)[number];

export function fixtureName(kind: DesktopKind): string {
  return `TSM_PvP_${kind}_2026-11-25.csv`;
}

export function readFixture(kind: DesktopKind): FileInput {
  const name = fixtureName(kind);
  return { name, text: readFileSync(join(FIXTURE_DIR, name), "utf8") };
}

export function readAllFixtures(): FileInput[] {
  return DESKTOP_KINDS.map(readFixture);
}
